<div class="page-title"><div><em>PAYMENTS</em><h1>Beneficiaries</h1><p>Manage the people and businesses you pay.</p></div><button class="btn" data-modal="beneficiary-modal">+ Add beneficiary</button></div><?php if(!$beneficiaries):?><div class="empty">You haven't added any beneficiaries yet. Add one to make transfers faster.</div><?php endif?><section class="panel list"><?php foreach($beneficiaries as $b):?><div class="list-row"><span class="avatar"><?=initials($b['name'])?></span><div><b><?=html_escape($b['name'])?></b><small><?=html_escape($b['bank_name'])?> · <?=html_escape($b['account_number'])?></small></div><span class="<?=status_class($b['status'])?>"><?=ucfirst($b['status'])?></span><a class="outline" href="<?=site_url('transfer')?>">Send money</a><button class="icon-btn" data-ben-edit data-base="<?=site_url('beneficiaries')?>" data-id="<?=$b['id']?>" data-name="<?=html_escape($b['name'])?>" data-account="<?=html_escape($b['account_number'])?>" data-bank="<?=html_escape($b['bank_name'])?>" data-routing="<?=html_escape($b['routing_code'])?>" data-currency="<?=html_escape($b['currency'])?>">✎</button><form method="post" action="<?=site_url('beneficiaries/'.$b['id'].'/delete')?><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>">" class="inline-del" onsubmit="return confirm('Remove this beneficiary?');"><button class="icon-btn danger">🗑</button></form></div><?php endforeach?></section><dialog id="beneficiary-modal"><div class="dialog-head"><h2>Add beneficiary</h2><button data-close>×</button></div><?=form_open('beneficiaries')?><label>Name</label><input name="name" required><label>Account number</label><input name="account_number" required><label>Bank name</label><input name="bank_name" required><label>Routing / SWIFT code</label><input name="routing_code"><button class="btn wide">Add beneficiary</button></form></dialog><dialog id="ben-edit-modal"><div class="dialog-head"><h2>Edit beneficiary</h2><button data-close>×</button></div><form method="post" id="ben-edit-form"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><label>Name</label><input name="name" id="ben-name" required><label>Account number</label><input name="account_number" id="ben-account" required><label>Bank name</label><input name="bank_name" id="ben-bank" required><label>Routing / SWIFT code</label><input name="routing_code" id="ben-routing"><button class="btn wide">Save changes</button></form></dialog><script>document.querySelectorAll('[data-ben-edit]').forEach(function(b){b.addEventListener('click',function(){document.getElementById('ben-edit-form').action=b.dataset.base+'/'+b.dataset.id+'/update';document.getElementById('ben-name').value=b.dataset.name;document.getElementById('ben-account').value=b.dataset.account;document.getElementById('ben-bank').value=b.dataset.bank;document.getElementById('ben-routing').value=b.dataset.routing;document.getElementById('ben-edit-modal').showModal();});});</script>
